+    [Parameter] public string? InitialCoverLetter { get; set; }
+    [Parameter] public EventCallback<string> OnNext { get; set; }
+    [Parameter] public EventCallback OnBack { get; set; }
+
+    private string CoverLetter { get; set; } = string.Empty;
+    private string? ErrorMessage { get; set; }
+
+    protected override void OnParametersSet()
+    {
+        if (InitialCoverLetter is not null)
+        {
+            CoverLetter = InitialCoverLetter;
+        }
+    }
+
+    private async Task HandleNext()
+    {
+        ErrorMessage = null;
+
+        if (string.IsNullOrWhiteSpace(CoverLetter))
+        {
+            ErrorMessage = "Please write a cover letter.";
+            return;
+        }
+
+        await OnNext.InvokeAsync(CoverLetter);
+    }
+}
